import React, { ReactNode } from 'react';
import { Container } from '@fiverr-private/layout_components';
import { type Types } from '@fiverr-private/theme';

interface CollapsibleHeaderMenuProps
  extends Pick<
    Types.ContainerProps,
    | 'flex'
    | 'flexShrink'
    | 'flexBasis'
    | 'flexGrow'
    | 'transform'
    | 'transition'
    | 'onClick'
    | 'dataTrackTag'
    | 'dataTrackValue'
  > {
  children: ReactNode | ReactNode[];
}

const CollapsibleHeaderMenu = ({
  children,
  onClick,
  dataTrackTag = 'collapsible_header_menu',
  ...restProps
}: CollapsibleHeaderMenuProps) => (
  <Container
    onClick={(e) => {
      e.stopPropagation();
      onClick?.(e);
    }}
    dataTrackTag={dataTrackTag}
    {...restProps}
  >
    {children}
  </Container>
);

CollapsibleHeaderMenu.displayName = 'CollapsibleHeaderMenu';
CollapsibleHeaderMenu.id = 'CollapsibleHeaderMenu';
export default CollapsibleHeaderMenu;
